#!/usr/bin/env Rscript
# packages/historicaldata/data-raw/make_sample_data.R
#
# Deterministic, seeded generator for the bundled sample Parquet fixtures at
# inst/extdata/sample/*.parquet. These fixtures back HD_USE_SAMPLE_DATA=1,
# the test-only resolver seam (see hd_dataset_source() in R/registry.R) that
# makes the package test suite hermetic against a live hf:// endpoint
# (issue #580 Phase 2).
#
# Provenance (reproducible-ingestion rule): every value below is synthetic,
# generated by this script from set.seed(42) and literal 2024 calendar
# dates -- NOT derived from any real market data, and NOT hand-typed. Ticker
# symbols reuse real large-cap US tickers as plausible labels only; the
# price/volume/metadata series attached to them are fabricated. Re-running
# this script reproduces byte-identical numeric content every time (Parquet
# writer metadata such as creation timestamps may differ). This discharges
# the technical debt the previous hand-committed sample_*.parquet files
# carried: no generator, no audit trail, no way to regenerate or extend them.
#
# Regenerate with (from the repo root, inside the project's Nix flake shell):
#   nix develop --command Rscript packages/historicaldata/data-raw/make_sample_data.R
#
# Design constraints (locked, #580 Phase 2 spec):
#   - equity_sample keeps the LEGACY 'adjusted' column name (not
#     'adjusted_close') so the #325 read-time alias path stays under test.
#   - equity_sample / crypto_sample 'date' is POSIXct (TIMESTAMP), matching
#     the real HF schema and exercising the #453 date-type probe.
#   - macro_sample / factors_sample 'date' is Date, matching the real HF
#     schema for those datasets.
#   - Column sets match packages/historicaldata/R/registry.R::hd_datasets()
#     schemas exactly (after the 'adjusted' -> 'adjusted_close' alias for
#     equity_daily).

suppressPackageStartupMessages({
  library(tibble)
})

set.seed(42)

# ---------------------------------------------------------------------------
# Locate output directory. Must be run from the repo root (the flake root),
# not from inside packages/historicaldata/.
# ---------------------------------------------------------------------------
out_dir <- file.path("packages", "historicaldata", "inst", "extdata", "sample")
if (!dir.exists(out_dir)) {
  stop(
    "Cannot find '", out_dir, "'. Run this script from the repo root, e.g.\n",
    "  nix develop --command Rscript packages/historicaldata/data-raw/make_sample_data.R"
  )
}

# ---------------------------------------------------------------------------
# Date helpers -- fixed literal 2024 ranges, no Sys.time()/Sys.Date().
# ---------------------------------------------------------------------------

# Return `n` consecutive weekday (Mon-Fri) dates starting at `start_date`.
.business_days <- function(start_date, n) {
  d <- as.Date(start_date)
  out <- vector("list", n)
  i <- 0L
  while (i < n) {
    if (!(weekdays(d) %in% c("Saturday", "Sunday"))) {
      i <- i + 1L
      out[[i]] <- d
    }
    d <- d + 1L
  }
  do.call(c, out)
}

EQUITY_DATES <- .business_days("2024-01-02", 32L)   # Tue 2024-01-02 .. (32 weekdays)
CRYPTO_DATES <- as.Date("2024-01-01") + 0:39         # 40 consecutive calendar days
MACRO_DATES  <- EQUITY_DATES                         # reuse equity's weekday calendar
FACTOR_DATES <- EQUITY_DATES

cat("EQUITY_DATES range:", format(min(EQUITY_DATES)), "..", format(max(EQUITY_DATES)),
    "(", length(EQUITY_DATES), "obs)\n")
cat("CRYPTO_DATES range:", format(min(CRYPTO_DATES)), "..", format(max(CRYPTO_DATES)),
    "(", length(CRYPTO_DATES), "obs)\n")

# ---------------------------------------------------------------------------
# Equity universe: AAPL, MSFT + 53 more large-cap US tickers (labels only;
# price series are synthetic). Total 55 tickers, keeping
# hd_tickers("equity_daily") length >= 50 a real assertion.
# ---------------------------------------------------------------------------
EQUITY_TICKERS <- c(
  "AAPL", "MSFT",
  "GOOGL", "AMZN", "NVDA", "TSLA", "META", "BRKB", "JPM", "V",
  "JNJ", "WMT", "PG", "MA", "HD", "CVX", "ABBV", "PFE", "KO", "PEP",
  "MRK", "COST", "TMO", "DIS", "ADBE", "CSCO", "XOM", "ACN", "MCD", "ABT",
  "DHR", "NKE", "LIN", "TXN", "NEE", "PM", "UNH", "VZ", "INTC", "WFC",
  "BMY", "RTX", "HON", "UPS", "T", "LOW", "ORCL", "IBM", "CAT", "GS",
  "BA", "SBUX", "MMM", "GE", "AMD"
)
stopifnot(length(EQUITY_TICKERS) == 55L, all(c("AAPL", "MSFT") %in% EQUITY_TICKERS))

CRYPTO_TICKERS <- c("BTC", "ETH")

# One deterministic base price per equity ticker (order fixed above, so
# regeneration is byte-stable given the same seed).
EQUITY_BASE_PRICE <- stats::setNames(
  round(runif(length(EQUITY_TICKERS), min = 20, max = 500), 2),
  EQUITY_TICKERS
)
# Keep AAPL/MSFT in a realistic large-cap range for readability.
EQUITY_BASE_PRICE[["AAPL"]] <- 185.00
EQUITY_BASE_PRICE[["MSFT"]] <- 370.00

CRYPTO_BASE_PRICE <- c(BTC = 42500, ETH = 2300)

# ---------------------------------------------------------------------------
# OHLCV generator (shared by equity + crypto)
# ---------------------------------------------------------------------------
.make_ohlcv <- function(ticker, dates, base_price, day_vol = 0.02,
                         adjusted_col = NULL, asset_class, updated_at) {
  n <- length(dates)
  rets <- rnorm(n, mean = 0.0002, sd = day_vol)
  close <- base_price * cumprod(1 + rets)
  prev_close <- c(base_price, close[-n])
  open <- prev_close * (1 + rnorm(n, 0, day_vol * 0.3))
  hi_lo_spread <- abs(rnorm(n, 0, day_vol * 0.5))
  high <- pmax(open, close) * (1 + hi_lo_spread)
  low  <- pmin(open, close) * (1 - hi_lo_spread)
  volume <- round(runif(n, 1e6, 8e7))

  out <- tibble::tibble(
    date   = dates,
    open   = round(open, 2),
    high   = round(high, 2),
    low    = round(low, 2),
    close  = round(close, 2),
    volume = volume,
    ticker = ticker,
    source = "synthetic",
    asset_class = asset_class,
    updated_at = updated_at
  )

  if (!is.null(adjusted_col)) {
    # Legacy pre-#325 column name 'adjusted' -- deliberately NOT renamed to
    # 'adjusted_close' here so the read-time alias in hd_ohlcv_single()/
    # hd_lazy() stays exercised by the hermetic test suite.
    out[[adjusted_col]] <- round(out$close * 0.99, 2)
    out <- out[, c("date", "open", "high", "low", "close", adjusted_col,
                   "volume", "ticker", "source", "asset_class", "updated_at")]
  }
  out
}

UPDATED_AT <- as.POSIXct("2024-03-15 00:00:00", tz = "UTC")

equity_rows <- lapply(EQUITY_TICKERS, function(tk) {
  .make_ohlcv(
    ticker = tk,
    dates = as.POSIXct(EQUITY_DATES, tz = "UTC"),
    base_price = EQUITY_BASE_PRICE[[tk]],
    day_vol = 0.018,
    adjusted_col = "adjusted",
    asset_class = "equity",
    updated_at = UPDATED_AT
  )
})
equity_sample <- dplyr::bind_rows(equity_rows)

crypto_rows <- lapply(CRYPTO_TICKERS, function(tk) {
  .make_ohlcv(
    ticker = tk,
    dates = as.POSIXct(CRYPTO_DATES, tz = "UTC"),
    base_price = CRYPTO_BASE_PRICE[[tk]],
    day_vol = 0.035,
    adjusted_col = NULL,
    asset_class = "crypto",
    updated_at = UPDATED_AT
  )
})
crypto_sample <- dplyr::bind_rows(crypto_rows)

# ---------------------------------------------------------------------------
