  sector              = sectors,
  industry            = paste(sectors, "Sub-Industry"),
  country             = "United States",
  market_cap          = round(runif(n_eq, 5e10, 3.5e12)),
  volume_avg          = round(runif(n_eq, 1e6, 8e7)),
  fifty_two_week_high = round(EQUITY_BASE_PRICE[EQUITY_TICKERS] * 1.25, 2),
  fifty_two_week_low  = round(EQUITY_BASE_PRICE[EQUITY_TICKERS] * 0.75, 2),
  expense_ratio       = NA_real_,
  yield_pct           = NA_real_,
  category            = NA_character_,
  fund_family         = NA_character_,
  nav_price           = NA_real_,
  beta_3yr            = round(runif(n_eq, 0.6, 1.6), 3),
  ytd_return          = round(runif(n_eq, -0.3, 0.4), 3),
  three_yr_return     = round(runif(n_eq, -0.2, 0.6), 3),
  start_date          = min(EQUITY_DATES),
  end_date            = max(EQUITY_DATES),
  total_obs           = length(EQUITY_DATES),
  missing_pct         = 0,
  yield_type          = NA_character_,
  short_name          = EQUITY_TICKERS,
  quote_type          = "EQUITY",
