  source              = "synthetic"
)

metadata_crypto <- tibble::tibble(
  ticker              = CRYPTO_TICKERS,
  dataset             = "crypto_daily",
  long_name           = c("Bitcoin USD", "Ethereum USD"),
  exchange            = "CCC",
  full_exchange       = "CCC",
  currency            = "USD",
  instrument_type     = "CRYPTOCURRENCY",
  sector              = NA_character_,
  industry            = NA_character_,
  country             = NA_character_,
  market_cap          = round(runif(n_cr, 1e11, 1e12)),
  volume_avg          = round(runif(n_cr, 1e9, 5e10)),
