metadata_sample <- dplyr::bind_rows(metadata_equity, metadata_crypto)

# ---------------------------------------------------------------------------
# Factors: Fama-French 3-factor daily, matches registry `factors` schema
# exactly (date, factor_name, value, dataset, frequency, source, updated_at).
# ---------------------------------------------------------------------------
FACTOR_NAMES <- c("Mkt-RF", "SMB", "HML", "RF")
factors_sample <- do.call(rbind, lapply(FACTOR_NAMES, function(fname) {
  tibble::tibble(
    date        = FACTOR_DATES,
    factor_name = fname,
    value       = round(rnorm(length(FACTOR_DATES), mean = if (fname == "RF") 0.01 else 0, sd = 0.5), 2),
    dataset     = "FF3",
    frequency   = "daily",
    source      = "french",
    updated_at  = UPDATED_AT
  )
}))

# ---------------------------------------------------------------------------
